{
  "lecture": [
    {
      "etiquette": "F40",
      "R1": {
        "valeur": 1,
        "passage": "À dollars égaux, la part des composantes conditionnelles couvertes par les retenues après 2 générations passe d'au plus 10 % pour le témoin à au moins 30 % pour le bras tableau croisé."
      },
      "R2": {
        "valeur": 1,
        "passage": "Oracle lu une fois : composantes conditionnelles et non conditionnelles couvertes, aux trois étages ; lois fausses et copies promues."
      },
      "R3": {
        "valeur": 1,
        "passage": "Le tableau n'est ni un verdict, ni l'oracle, ni la loi plantée, ni un score de juge ou de moniteur : ce sont des effectifs bruts d'épisodes publics."
      },
      "R4": {
        "valeur": 1,
        "passage": "levier:proposeurs"
      },
      "R5": {
        "valeur": 1,
        "passage": "Chaque trait continu est coupé à sa médiane sur cet échantillon. Pour chaque paire non ordonnée de traits, le tableau donne les effectifs et la fréquence de chaque issue dans les quatre cases."
      },
      "R6": {
        "valeur": 1,
        "passage": "Bon marché d'abord : un modèle peu cher, 20 mondes, 3 bras (témoin, croisé, placebo), 2 générations, environ 400 appels, soit des dizaines de dollars."
      },
      "R7": {
        "valeur": 1,
        "passage": "Elle laisse en revanche une pente de signe opposé dans les deux branches d'un croisement à deux traits. Un proposeur qui voit ce croisement peut la proposer avant même que sa condition soit archivée."
      },
      "N": {
        "valeur": "aucune"
      }
    },
    {
      "etiquette": "F41",
      "R1": {
        "valeur": 1,
        "passage": "à épisodes frais égaux par carte, au moins deux composantes plantées de plus couvertes par monde en moyenne sur les quarante mondes"
      },
      "R2": {
        "valeur": 0,
        "motif": "La prédiction impose aussi une proportion de cartes validées avant la cinquième épreuve, métrique dépendant des décisions du juge et non du seul oracle ou coût mesuré."
      },
      "R3": {
        "valeur": 0,
        "motif": "Le piège envisage que l'agent choisisse les épreuves suivantes au vu des valeurs obtenues et répond par des précautions statistiques sans interdire ce retour de scores à l'agent."
      },
      "R4": {
        "valeur": 0,
        "motif": "La fiche annonce un contrôle de première espèce et e-BH, mais ne définit pas le nul contre lequel cette garantie reste démontrable."
      },
      "R5": {
        "valeur": 0,
        "motif": "Le calibrateur p-vers-e, le calcul de la valeur p contre le nul composite et l'information fournie au concepteur des épreuves restent indéterminés."
      },
      "R6": {
        "valeur": 1,
        "passage": "quelques dollars d'agent concepteur par génération, de l'ordre de 2 à 4 USD, soit 80 à 160 USD pour quarante mondes, plus le rejeu du juge actuel sur processeur"
      },
      "R7": {
        "valeur": 0,
        "motif": "La validité sous arrêt optionnel et le ciblage des divergences avec l'archive ne suffisent pas à impliquer une meilleure couverture à épisodes égaux, notamment lorsque ces divergences sont déjà couvertes par les recombinaisons du nul."
      },
      "N": {
        "valeur": "C2",
        "passage_fiche": "Chaque épreuve vise la région des traits où la carte et l'archive divergent le plus et rend une valeur p, convertie en valeur e ; les valeurs e se multiplient, et la carte n'est validée que si leur produit dépasse 1/α",
        "passage_catalogue": "**Falsification séquentielle** d'une hypothèse : un agent conçoit des expériences de falsification successives ; chaque valeur p est convertie en **valeur e** ; les valeurs e se combinent ; l'hypothèse est validée quand la valeur e combinée dépasse 1/α, avec **contrôle de l'erreur de première espèce**."
      }
    },
    {
      "etiquette": "F42",
      "R1": {
        "valeur": 1,
        "passage": "du nombre de composantes distinctes couvertes à l'étage des propositions brutes est supérieure d'au moins 1 dans le bras à constats, bien qu'il rende six cartes contre 6·K au témoin"
      },
      "R2": {
        "valeur": 1,
        "passage": "Oracle : composantes certifiées couvertes, étages des propositions brutes, des représentants et des retenues ; lois fausses et copies promues."
      },
      "R3": {
        "valeur": 1,
        "passage": "Aucun modèle ne note, ne trie, ni ne filtre les constats. Extraction, gardien, regroupement des doublons, juge inchangés."
      },
      "R4": {
        "valeur": 1,
        "passage": "levier:proposeurs"
      },
      "R5": {
        "valeur": 1,
        "passage": "appels 2 à 7 (sessions neuves, sans historique) = vue habituelle complète + un seul constat (le i-ème, dans l'ordre rendu, sans tri) + consigne d'une carte au gabarit"
      },
      "R6": {
        "valeur": 1,
        "passage": "15 mondes × 4 proposeurs × (7 appels courts + K appels témoin) en génération 1 ; ordre de quelques dizaines de dollars, devis avant feu vert."
      },
      "R7": {
        "valeur": 1,
        "passage": "Le passage par une liste de constats déclarés, puis l'isolement de chacun dans une session qui ne voit pas les autres, supprime la pression de cohérence interne d'un appel unique"
      },
      "N": {
        "valeur": "aucune"
      }
    },
    {
      "etiquette": "F43",
      "R1": {
        "valeur": 1,
        "passage": "À dollars totaux égaux : composantes de profondeur 1 et 2 couvertes aux retenues : au moins +2 sur la somme des 10 mondes pour le bras testé"
      },
      "R2": {
        "valeur": 1,
        "passage": "Oracle : composantes certifiées couvertes par profondeur (surface, 1, 2), à chaque génération et aux retenues finales ; lois fausses et copies promues."
      },
      "R3": {
        "valeur": 1,
        "passage": "arrêt par plafond, jamais par verdict du juge ; (4) juge, gardien, regroupement, archive inchangés ; aucun score ni coût servi aux proposeurs."
      },
      "R4": {
        "valeur": 1,
        "passage": "levier:cout"
      },
      "R5": {
        "valeur": 0,
        "motif": "La fiche ne précise ni quels instruments locaux employer ni leur nombre, informations nécessaires pour programmer le remplacement des proposeurs de génération 1."
      },
      "R6": {
        "valeur": 1,
        "passage": "10 mondes × 2 bras × 3 à 4 générations × 4 proposeurs ; ordre d'une centaine de dollars pour la frontière, calcul local en sus ; devis avant feu vert."
      },
      "R7": {
        "valeur": 0,
        "motif": "À coût de frontière par génération identique, G+1 générations dont une locale coûtent G générations de frontière plus la génération locale : le remplacement ne finance donc pas la génération supplémentaire invoquée pour expliquer le gain."
      },
      "N": {
        "valeur": "aucune"
      }
    }
  ]
}
